import React, { useState, useEffect } from 'react';
import {
  Card,
  Form,
  Input,
  Button,
  ColorPicker,
  Space,
  Typography,
  Row,
  Col,
  Select,
  Divider,
  Modal,
  Tabs,
  Tag,
  App
} from 'antd';
import {
  PlusOutlined,
  SaveOutlined,
  DeleteOutlined,
  EyeOutlined,
  SettingOutlined
} from '@ant-design/icons';

const { Title, Text } = Typography;
const { Option } = Select;

interface ThemeColors {
  // Фоны
  bg_primary: string;
  bg_secondary: string;
  bg_card: string;
  bg_hover: string;
  bg_topbar: string;
  
  // Тексты
  text_primary: string;
  text_secondary: string;
  text_hint: string;
  
  // Акценты и кнопки
  primary_color: string;
  primary_hover: string;
  secondary_color: string;
  accent_color: string;
  success_color: string;
  danger_color: string;
  warning_color: string;
  
  // Границы
  border_color: string;
  border_light: string;
  
  // Градиенты
  grad_start: string;
  grad_end: string;
}

interface Theme {
  id?: number;
  name: string;
  is_active: boolean;
  is_custom: boolean;
  colors: ThemeColors;
}

const ThemeEditor: React.FC = () => {
  const { message } = App.useApp();
  const [themes, setThemes] = useState<Theme[]>([]);
  const [currentTheme, setCurrentTheme] = useState<Theme | null>(null);
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);
  const [previewMode, setPreviewMode] = useState(false);

  // Дефолтные цвета
  const defaultColors: ThemeColors = {
    bg_primary: '#0f0f0f',
    bg_secondary: '#1a1a1a',
    bg_card: '#2a2a2a',
    bg_hover: '#3a3a3a',
    bg_topbar: 'rgba(15,15,15,0.85)',
    text_primary: '#ffffff',
    text_secondary: '#a0a0a0',
    text_hint: '#666666',
    primary_color: '#6366f1',
    primary_hover: '#5048e5',
    secondary_color: '#8b5cf6',
    accent_color: '#f59e0b',
    success_color: '#10b981',
    danger_color: '#ef4444',
    warning_color: '#f59e0b',
    border_color: '#404040',
    border_light: '#303030',
    grad_start: '#1a1a3a',
    grad_end: '#0f0f0f',
  };

  // Загрузка тем
  const loadThemes = async () => {
    try {
      const response = await fetch('/api/miniapp/themes/dev');
      if (response.ok) {
        const data = await response.json();
        setThemes(data.themes || []);
      }
    } catch (error) {
      console.error('Ошибка загрузки тем:', error);
    }
  };

  // Сохранение темы
  const saveTheme = async (values: any) => {
    setLoading(true);
    try {
      const response = await fetch('/api/miniapp/themes/dev', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          id: currentTheme?.id,
          name: values.name,
          colors: values.colors,
        }),
      });

      if (response.ok) {
        message.success('Тема сохранена!');
        loadThemes();
      } else {
        message.error('Ошибка сохранения темы');
      }
    } catch (error) {
      console.error('Ошибка сохранения:', error);
      message.error('Ошибка сохранения темы');
    }
    setLoading(false);
  };

  // Активация темы
  const activateTheme = async (themeId: number) => {
    try {
      const response = await fetch(`/api/miniapp/themes/dev/${themeId}/activate`, {
        method: 'POST',
      });

      if (response.ok) {
        message.success('Тема активирована!');
        loadThemes();
        applyThemeToPreview(themes.find(t => t.id === themeId)?.colors || defaultColors);
      } else {
        message.error('Ошибка активации темы');
      }
    } catch (error) {
      console.error('Ошибка активации:', error);
      message.error('Ошибка активации темы');
    }
  };

  // Удаление темы
  const deleteTheme = async (themeId: number) => {
    Modal.confirm({
      title: 'Удалить тему?',
      content: 'Это действие нельзя отменить.',
      okText: 'Удалить',
      cancelText: 'Отмена',
      okType: 'danger',
      onOk: async () => {
        try {
          const response = await fetch(`/api/miniapp/themes/dev/${themeId}`, {
            method: 'DELETE',
          });

          if (response.ok) {
            message.success('Тема удалена!');
            loadThemes();
          } else {
            message.error('Ошибка удаления темы');
          }
        } catch (error) {
          console.error('Ошибка удаления:', error);
          message.error('Ошибка удаления темы');
        }
      },
    });
  };

  // Применение темы для превью
  const applyThemeToPreview = (colors: ThemeColors) => {
    const root = document.documentElement;
    Object.entries(colors).forEach(([key, value]) => {
      root.style.setProperty(`--${key.replace(/_/g, '-')}`, value);
    });
  };

  // Создание новой темы
  const createNewTheme = () => {
    const newTheme: Theme = {
      name: 'Новая тема',
      is_active: false,
      is_custom: true,
      colors: { ...defaultColors },
    };
    setCurrentTheme(newTheme);
    // Используем resetFields и setFieldsValue отдельно для избежания предупреждений
    form.resetFields();
    setTimeout(() => {
      form.setFieldsValue({
        name: newTheme.name,
        colors: newTheme.colors,
      });
    }, 0);
  };

  // Редактирование существующей темы
  const editTheme = (theme: Theme) => {
    setCurrentTheme(theme);
    form.setFieldsValue({
      name: theme.name,
      colors: theme.colors,
    });
  };

  useEffect(() => {
    loadThemes();
  }, []);

  const colorGroups = [
    {
      title: 'Фоны',
      icon: '🎨',
      colors: [
        { key: 'bg_primary', label: 'Основной фон', description: 'Фон всего приложения' },
        { key: 'bg_secondary', label: 'Вторичный фон', description: 'Фон для меню и боковых панелей' },
        { key: 'bg_card', label: 'Фон карточек', description: 'Фон карточек и модальных окон' },
        { key: 'bg_hover', label: 'Фон при наведении', description: 'Цвет при наведении мыши' },
        { key: 'bg_topbar', label: 'Фон заголовка', description: 'Фон верхней панели' },
      ]
    },
    {
      title: 'Тексты',
      icon: '📝',
      colors: [
        { key: 'text_primary', label: 'Основной текст', description: 'Цвет основного текста' },
        { key: 'text_secondary', label: 'Вторичный текст', description: 'Цвет подписей и описаний' },
        { key: 'text_hint', label: 'Подсказки', description: 'Цвет подсказок и плейсхолдеров' },
      ]
    },
    {
      title: 'Акценты',
      icon: '🌟',
      colors: [
        { key: 'primary_color', label: 'Основной акцент', description: 'Главный цвет интерфейса' },
        { key: 'primary_hover', label: 'Акцент при наведении', description: 'Цвет кнопок при наведении' },
        { key: 'secondary_color', label: 'Вторичный акцент', description: 'Дополнительный акцентный цвет' },
        { key: 'accent_color', label: 'Выделение', description: 'Цвет для выделения элементов' },
      ]
    },
    {
      title: 'Статусы',
      icon: '🚦',
      colors: [
        { key: 'success_color', label: 'Успех', description: 'Цвет успешных операций' },
        { key: 'danger_color', label: 'Ошибка', description: 'Цвет ошибок и предупреждений' },
        { key: 'warning_color', label: 'Предупреждение', description: 'Цвет предупреждений' },
      ]
    },
    {
      title: 'Границы и градиенты',
      icon: '🔲',
      colors: [
        { key: 'border_color', label: 'Границы', description: 'Цвет границ элементов' },
        { key: 'border_light', label: 'Светлые границы', description: 'Цвет тонких границ' },
        { key: 'grad_start', label: 'Начало градиента', description: 'Начальный цвет фонового градиента' },
        { key: 'grad_end', label: 'Конец градиента', description: 'Конечный цвет фонового градиента' },
      ]
    }
  ];

  return (
    <div className="theme-editor">
      <Card>
        <Title level={3}>
          <SettingOutlined /> Редактор тем
        </Title>
        <Text type="secondary">
          Создавайте и настраивайте свои уникальные темы оформления
        </Text>
        
        <Divider />
        
        <Tabs 
          defaultActiveKey="list"
          items={[
            {
              key: 'list',
              label: 'Мои темы',
              children: (
                <Row gutter={[16, 16]}>
                  <Col span={24}>
                    <Button 
                      type="primary" 
                      icon={<PlusOutlined />}
                      onClick={createNewTheme}
                      style={{ marginBottom: 16 }}
                    >
                      Создать новую тему
                    </Button>
                  </Col>
                  
                  {themes.map((theme) => (
                    <Col xs={24} sm={12} md={8} key={theme.id}>
                      <Card
                        size="small"
                        actions={[
                          <Button 
                            type="text" 
                            icon={<EyeOutlined />}
                            onClick={() => editTheme(theme)}
                          >
                            Изменить
                          </Button>,
                          <Button 
                            type="text" 
                            onClick={() => theme.id && activateTheme(theme.id)}
                            disabled={theme.is_active}
                          >
                            {theme.is_active ? 'Активна' : 'Применить'}
                          </Button>,
                          theme.is_custom && (
                            <Button 
                              type="text" 
                              danger
                              icon={<DeleteOutlined />}
                              onClick={() => theme.id && deleteTheme(theme.id)}
                            />
                          )
                        ].filter(Boolean)}
                      >
                        <div style={{ textAlign: 'center' }}>
                          <Title level={5}>{theme.name}</Title>
                          <div style={{ display: 'flex', justifyContent: 'center', gap: 4, margin: '8px 0' }}>
                            <div 
                              style={{
                                width: 20,
                                height: 20,
                                backgroundColor: theme.colors.primary_color,
                                borderRadius: 4,
                              }}
                            />
                            <div 
                              style={{
                                width: 20,
                                height: 20,
                                backgroundColor: theme.colors.bg_card,
                                border: '1px solid #ccc',
                                borderRadius: 4,
                              }}
                            />
                            <div 
                              style={{
                                width: 20,
                                height: 20,
                                backgroundColor: theme.colors.text_primary,
                                borderRadius: 4,
                              }}
                            />
                          </div>
                          <Space>
                            {theme.is_active && <Tag color="green">Активна</Tag>}
                            {theme.is_custom ? <Tag>Пользовательская</Tag> : <Tag color="blue">Системная</Tag>}
                          </Space>
                        </div>
                      </Card>
                    </Col>
                  ))}
                </Row>
              )
            },
            {
              key: 'editor',
              label: 'Редактор',
              disabled: !currentTheme,
              children: currentTheme && (
                <Form
                  form={form}
                  layout="vertical"
                  onFinish={saveTheme}
                  initialValues={{
                    name: currentTheme.name,
                    colors: currentTheme.colors,
                  }}
                >
                  <Row gutter={[24, 16]}>
                    <Col span={24}>
                      <Form.Item
                        label="Название темы"
                        name="name"
                        rules={[{ required: true, message: 'Введите название темы' }]}
                      >
                        <Input placeholder="Моя уникальная тема" />
                      </Form.Item>
                    </Col>
                  </Row>
                  
                  {colorGroups.map((group) => (
                    <div key={group.title}>
                      <Title level={4}>
                        {group.icon} {group.title}
                      </Title>
                      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                        {group.colors.map((colorConfig) => (
                          <Col xs={24} sm={12} md={8} key={colorConfig.key}>
                            <Form.Item
                              label={colorConfig.label}
                              name={['colors', colorConfig.key]}
                              tooltip={colorConfig.description}
                            >
                              <ColorPicker
                                showText
                                size="large"
                                onChange={(color) => {
                                  const hex = color.toHexString();
                                  // Простое обновление без deepEqual проверок
                                  const newColors = { ...form.getFieldValue('colors') };
                                  newColors[colorConfig.key] = hex;
                                  form.setFieldValue('colors', newColors);
                                  // Применяем изменения в реальном времени для превью
                                  if (previewMode) {
                                    const root = document.documentElement;
                                    root.style.setProperty(`--${colorConfig.key.replace(/_/g, '-')}`, hex);
                                  }
                                }}
                              />
                            </Form.Item>
                          </Col>
                        ))}
                      </Row>
                    </div>
                  ))}
                  
                  <Divider />
                  
                  <Row gutter={[16, 16]}>
                    <Col>
                      <Button
                        type="primary"
                        icon={<SaveOutlined />}
                        htmlType="submit"
                        loading={loading}
                      >
                        Сохранить тему
                      </Button>
                    </Col>
                    <Col>
                      <Button
                        icon={<EyeOutlined />}
                        onClick={() => {
                          setPreviewMode(!previewMode);
                          if (!previewMode) {
                            const colors = form.getFieldValue('colors');
                            applyThemeToPreview(colors);
                          }
                        }}
                      >
                        {previewMode ? 'Отключить превью' : 'Превью'}
                      </Button>
                    </Col>
                  </Row>
                </Form>
              )
            }
          ]}
        />
      </Card>
    </div>
  );
};

export default ThemeEditor;
